r.del_flag = '0' and r.owner_user_id = #{ownerUserId}
and ( r.conclusion like concat('%', #{keyword}, '%') or r.mistake like concat('%', #{keyword}, '%') or r.next_plan like concat('%', #{keyword}, '%') or exists ( select 1 from stock_review_trade sk where sk.review_id = r.review_id and sk.owner_user_id = r.owner_user_id and sk.del_flag = '0' and (sk.stock_code like concat('%', #{keyword}, '%') or sk.stock_name like concat('%', #{keyword}, '%') or sk.note like concat('%', #{keyword}, '%')) ) )
and r.mood = #{mood}
and exists ( select 1 from stock_review_trade tg where tg.review_id = r.review_id and tg.owner_user_id = r.owner_user_id and tg.del_flag = '0' and tg.result_tag = #{resultTag} )
and r.review_date >= #{params.beginReviewDate}
and r.review_date <= #{params.endReviewDate}
order by r.review_date desc, r.review_id desc


where r.review_id = #{reviewId}
  and r.owner_user_id = #{ownerUserId}
  and r.del_flag = '0'


where r.review_date = #{reviewDate}
  and r.owner_user_id = #{ownerUserId}
  and r.del_flag = '0'

select r.review_date as review_date,
       (select count(1) from stock_review_trade t
         where t.review_id = r.review_id and t.owner_user_id = r.owner_user_id and t.del_flag = '0') as trade_count
from stock_review r
where r.owner_user_id = #{ownerUserId}
  and r.del_flag = '0'
  and r.review_date >= #{beginDate}
  and r.review_date <= #{endDate}
order by r.review_date asc

select count(1) as reviewDays,
       coalesce(sum(case when exists (
           select 1 from stock_review_trade t
           where t.review_id = r.review_id and t.owner_user_id = r.owner_user_id and t.del_flag = '0'
       ) then 1 else 0 end), 0) as tradeDays,
       coalesce((
           select sum(t.profit_loss) from stock_review_trade t
           inner join stock_review rr on rr.review_id = t.review_id
           where t.owner_user_id = #{ownerUserId}
             and t.del_flag = '0'
             and rr.del_flag = '0'
             and rr.review_date >= #{beginDate}
             and rr.review_date <= #{endDate}
       ), 0) as profitLoss
from stock_review r
where r.owner_user_id = #{ownerUserId}
  and r.del_flag = '0'
  and r.review_date >= #{beginDate}
  and r.review_date <= #{endDate}

