select t.stock_code as stockCode, max(t.stock_name) as stockName from stock_review_trade t where t.owner_user_id = #{ownerUserId} and t.del_flag = '0' and t.stock_code is not null and t.stock_code != ''
and ( t.stock_code like concat('%', #{keyword}, '%') or t.stock_name like concat('%', #{keyword}, '%') )
group by t.stock_code order by max(t.create_time) desc, t.stock_code asc limit #{limit}

